
/* ===== Sumber data dari Google Sheets (CSV terpublikasi). Alamat diatur di data-config.js ===== */
function SIF_CSV(t){const rows=[];let r=[],f='',q=false;t=t.replace(/^﻿/,'');
  for(let i=0;i<t.length;i++){const c=t[i];
    if(q){if(c==='"'){if(t[i+1]==='"'){f+='"';i++}else q=false}else f+=c}
    else if(c==='"')q=true;else if(c===','){r.push(f);f=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&t[i+1]==='\n')i++;r.push(f);rows.push(r);r=[];f=''}else f+=c}
  if(f!==''||r.length){r.push(f);rows.push(r)}
  const h=(rows.shift()||[]).map(x=>x.trim().toLowerCase().replace(/\s+/g,'_'));
  return rows.filter(x=>x.some(v=>v.trim()!=='')).map(x=>Object.fromEntries(h.map((k,i)=>[k,(x[i]||'').trim()])));}
/* ===== Tata kelola data (Keputusan Bupati tentang SOP Pengelolaan Data SIF POINT BATARA) =====
   Baris pada tab Google Sheets yang memiliki kolom "terbit" hanya ditampilkan bila disetujui terbit (SOP-03 langkah 3). */
const SIF_YA=/^(ya|y|yes|true|1|terbit|disetujui|setuju)$/i;
function SIF_DATE(v){v=String(v||'').trim();let m=v.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);if(m)return new Date(+m[1],m[2]-1,+m[3]);
  m=v.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/);if(m)return new Date(+m[3],m[2]-1,+m[1]);return null}
function SIF_META1(k,v){const has=k!=='kontak'&&v.length>0&&('terbit' in v[0]);const rows=has?v.filter(r=>SIF_YA.test(String(r.terbit||'').trim())):v;
  let last=null;const ba=new Set(),st={};
  rows.forEach(r=>{const d=SIF_DATE(r.tanggal_mutakhir);if(d&&(!last||d>last))last=d;const b=String(r.nomor_ba||'').trim();if(b)ba.add(b);const s=String(r.status_data||'').trim().toLowerCase();if(s)st[s]=(st[s]||0)+1;});
  return {rows,total:v.length,terbit:rows.length,filter:has,last,ba:[...ba],st};}
/* model realisasi investasi: bawaan = paparan Bidang Penanaman Modal (LKPM Juli 2026); dapat diganti tab Realisasi */
function SIF_REAL(){
  const D={tahun:2026,tw:[['TW I',700,819],['TW II',1200,1346],['TW III',1800,null],['TW IV',2200,null]],target:2226,pma:55.7,tk:1620,lkpm:'Juli 2026',src:'',kalteng:null,sheet:false};
  const R=(window.SIF_OVR||{}).realisasi;let M=D;
  if(R){
    const num=v=>{v=String(v==null?'':v).replace(/\s/g,'').replace(/^Rp/i,'').replace(/%$/,'');if(!v||v==='-'||v==='–')return NaN;if(/^-?\d{1,3}(\.\d{3})+(,\d+)?$/.test(v))v=v.replace(/\./g,'');return parseFloat(v.replace(',','.'))};
    const twn=v=>({'1':1,'I':1,'2':2,'II':2,'3':3,'III':3,'4':4,'IV':4})[String(v||'').trim().toUpperCase().replace(/^(TW|TRIWULAN)\s*/,'')]||0;
    const rows=R.map(r=>({y:parseInt(r.tahun,10),q:twn(r.triwulan),t:num(r.target_kumulatif_miliar),r:num(r.realisasi_kumulatif_miliar),T:num(r.target_tahunan_miliar),pma:num(r.pma_kumulatif_miliar),pmdn:num(r.pmdn_kumulatif_miliar),tk:num(r.tenaga_kerja_kumulatif),lk:String(r.periode_lkpm||'').trim(),src:String(r.sumber||'').trim(),kt:num(r.kontribusi_target_kalteng_persen),pp:num(r.porsi_pma_persen)})).filter(x=>x.y>2000&&x.q);
    const ys=rows.filter(x=>isFinite(x.r)).map(x=>x.y);
    if(ys.length){const y=Math.max(...ys),Y=rows.filter(x=>x.y===y),at=q=>Y.filter(x=>x.q===q).pop();
      const tw=['TW I','TW II','TW III','TW IV'].map((n,i)=>{const x=at(i+1);return [n,x&&isFinite(x.t)?x.t:null,x&&isFinite(x.r)?x.r:null]});
      const L=Y.filter(x=>isFinite(x.r)).sort((a,b)=>a.q-b.q).pop(),TT=Y.map(x=>x.T).filter(isFinite);
      const target=TT.length?TT[TT.length-1]:(tw[3][1]||NaN);
      if(isFinite(target)&&target>0){const pm=isFinite(L.pma)&&isFinite(L.pmdn)&&L.pma+L.pmdn>0?L.pma/(L.pma+L.pmdn)*100:isFinite(L.pp)&&L.pp>=0&&L.pp<=100?L.pp:null;const kt=Y.map(x=>x.kt).filter(isFinite);
        M={tahun:y,tw,target,pma:pm,tk:isFinite(L.tk)?L.tk:null,lkpm:L.lk,src:L.src,kalteng:kt.length?kt[kt.length-1]:null,sheet:true};}}
  }
  const f=(v,d)=>v.toLocaleString('id-ID',{minimumFractionDigits:d,maximumFractionDigits:d});
  const li=M.tw.reduce((a,x,i)=>x[2]!=null?i:a,0),real=M.tw[li][2],RN=['I','II','III','IV'];
  const big=real>=1000?['Rp'+f(real/1000,2),'triliun']:['Rp'+f(real,1),'miliar'],pct=real/M.target*100;
  const cap=M.tw.filter(x=>x[1]&&x[2]!=null).map(([n,t,r])=>[n,f(r/t*100,1),r/t*100]);
  const vals=M.tw.flatMap(x=>[x[1],x[2]]).filter(v=>v!=null);
  return Object.assign(M,{real,pct,twS:'TW '+RN[li],twL:'Triwulan '+RN[li]+' '+M.tahun,big,realT:big[0]+(real>=1000?' T':' M'),realM:'Rp'+f(real,0)+' M',
    targetTxt:M.target>=1000?'Rp'+(M.target/1000).toLocaleString('id-ID',{maximumFractionDigits:3})+' triliun':'Rp'+f(M.target,1)+' miliar',targetM:'Rp'+f(M.target,0)+' M',
    pctS:f(pct,1),tkS:M.tk!=null?f(M.tk,0):null,pmaS:M.pma!=null?f(M.pma,1):null,pmdnS:M.pma!=null?f(100-M.pma,1):null,cap,max:Math.max(2400,Math.ceil(Math.max(...vals)/600)*600)});
}
function SIF_KIRIM(jenis,obj){const A=(window.SIF_CFG||{}).api;if(!A||!/^\/api\/public$/.test(A))return Promise.resolve(null);
  return fetch(A+'/'+jenis,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(obj)}).then(r=>r.json().catch(()=>null)).catch(()=>null);}
function SIF_CATAT(out,pr){pr.then(j=>{if(!j||!out||!out.isConnected)return;const p=document.createElement('p');p.className='mx-kec';p.setAttribute('role','status');
  p.textContent=j.ok?'Tercatat otomatis di sistem SIF POINT BATARA dan diteruskan ke petugas DPMPTSP. Anda tetap dapat menyampaikan teks di bawah melalui kanal yang tersedia.':(j.error||'Pencatatan otomatis belum berhasil; sampaikan teks di bawah melalui kanal yang tersedia.');
  const k=out.querySelector('.kt-b');k?out.insertBefore(p,k):out.appendChild(p);});}
function SIF_LOAD(){
  const C=window.SIF_CFG||{},keys=['peluang','titik','pabrik','kecamatan','kontak','produksi','realisasi','mitra'].filter(k=>/^(https:\/\/|\/api\/public\/)/.test(C[k]||''));
  const geo={};try{const k=sessionStorage.getItem('sif_geo_kec'),d=sessionStorage.getItem('sif_geo_desa');if(k)geo.kec=JSON.parse(k);if(d)geo.desa=JSON.parse(d);if(k||d)geo.src='berkas uji (dimuat di peramban ini)';}catch(e){}
  const gj=u=>fetch(u,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(r.status);return r.json()}).catch(()=>null);
  const gp=(geo.kec||geo.desa)?Promise.resolve():Promise.all([C.batas_kecamatan?gj(C.batas_kecamatan):null,C.batas_desa?gj(C.batas_desa):null]).then(([k,d])=>{if(k)geo.kec=k;if(d)geo.desa=d;if(k||d)geo.src=C.batas_sumber||'berkas batas wilayah resmi';});
  const gdone=gp.then(()=>{if(geo.kec||geo.desa)window.SIF_GEO=geo;});
  if(!keys.length)return Promise.race([gdone,new Promise(r=>setTimeout(r,15000))]).catch(()=>{});
  const all=Promise.all(keys.map(k=>fetch(C[k],{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(r.status);return r.text()}).then(t=>[k,SIF_CSV(t)]).catch(()=>[k,null])))
    .then(a=>{const o={},M={};a.forEach(([k,v])=>{if(!v||!v.length)return;const m=SIF_META1(k,v);M[k]=m;if(m.rows.length)o[k]=m.rows});window.SIF_OVR=o;window.SIF_META=M;});
  return Promise.race([Promise.all([all,gdone]),new Promise(r=>setTimeout(r,15000))]).catch(()=>{});
}

