  /* ilustrasi fasilitas hilirisasi (SVG beranimasi) */
  function smoke(x,y,c){return [0,1,2].map(j=>`<circle cx="${x}" cy="${y}" r="5" fill="${c}" opacity="0"><animate attributeName="cy" values="${y};${y-38}" dur="3s" begin="${j}s" repeatCount="indefinite"/><animate attributeName="r" values="4;11" dur="3s" begin="${j}s" repeatCount="indefinite"/><animate attributeName="opacity" values=".55;0" dur="3s" begin="${j}s" repeatCount="indefinite"/></circle>`).join('')}
  function blink(x,y,c,d){return `<circle cx="${x}" cy="${y}" r="2.6" fill="${c}"><animate attributeName="opacity" values="1;.15;1" dur="${d||1.6}s" repeatCount="indefinite"/></circle>`}
  function belt(x1,x2,y,c){return `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="${c}" stroke-opacity=".5" stroke-width="3"/>`+[0,1,2].map(j=>`<rect y="${y-5}" width="8" height="5" rx="1" fill="${c}"><animate attributeName="x" values="${x1};${x2-8}" dur="2.4s" begin="${j*.8}s" repeatCount="indefinite"/></rect>`).join('')}
  function ground(c){return `<rect x="0" y="138" width="320" height="32" fill="${c}" fill-opacity=".10"/><line x1="0" y1="138" x2="320" y2="138" stroke="${c}" stroke-opacity=".6"/>`+Array.from({length:9},(_,i)=>`<line x1="${i*40}" y1="170" x2="${i*40+20}" y2="138" stroke="${c}" stroke-opacity=".12"/>`).join('')}
  function rows(x,y,w,n,c,plant){let s='';for(let r=0;r<n;r++)for(let i=0;i<w;i++){const px=x+i*14+(r%2)*7,py=y+r*8;s+=plant==='padi'?`<path d="M${px} ${py} q-3 -9 -6 -11 M${px} ${py} q0 -10 1 -13 M${px} ${py} q3 -9 6 -11" stroke="${c}" stroke-width="1.4" fill="none"/>`:plant==='jagung'?`<path d="M${px} ${py} v-16 M${px} ${py-8} q-6 -3 -8 -9 M${px} ${py-12} q6 -2 8 -8" stroke="${c}" stroke-width="1.4" fill="none"/><ellipse cx="${px+2}" cy="${py-11}" rx="1.8" ry="4" fill="#F2C14E"/>`:`<path d="M${px} ${py} v-12 M${px} ${py-12} q-9 0 -12 5 M${px} ${py-12} q9 0 12 5 M${px} ${py-12} q-5 -7 -10 -8 M${px} ${py-12} q5 -7 10 -8" stroke="${c}" stroke-width="1.4" fill="none"/>`;}return s}
  function factory(x,w,h,c,roof){const y=138-h;return `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/>`+(roof==='saw'?Array.from({length:Math.floor(w/22)},(_,i)=>`<path d="M${x+i*22} ${y} l11 -12 v12" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/>`).join(''):`<path d="M${x-4} ${y} L${x+w/2} ${y-18} L${x+w+4} ${y} Z" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/>`)+Array.from({length:Math.floor(w/18)},(_,i)=>`<rect x="${x+6+i*18}" y="${y+10}" width="9" height="7" fill="${c}" fill-opacity=".55"/>`).join('')+`<rect x="${x+w/2-8}" y="${138-18}" width="16" height="18" fill="${c}" fill-opacity=".25" stroke="${c}"/>`}
  function chimney(x,y,c){return `<rect x="${x}" y="${y}" width="9" height="${138-y}" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/>`+smoke(x+4.5,y-4,'#CFE9DA')}
  function silo(x,y,w,c){return `<rect x="${x}" y="${y}" width="${w}" height="${138-y}" rx="2" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/><path d="M${x} ${y} q${w/2} -12 ${w} 0" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/>`+[1,2,3].map(i=>`<line x1="${x}" x2="${x+w}" y1="${y+i*(138-y)/4}" y2="${y+i*(138-y)/4}" stroke="${c}" stroke-opacity=".35"/>`).join('')}
