    karet:c=>ground(c)+`${[20,52,84].map(x=>`<path d="M${x} 138 v-34" stroke="#9BD66B" stroke-width="3"/><circle cx="${x}" cy="96" r="16" fill="#1E5A35" stroke="#9BD66B"/><path d="M${x+1} 124 h6 v5 h-6z" fill="#FFF4CC"/>`).join('')}`+factory(124,120,54,c,'saw')+chimney(252,46,c)+belt(98,124,130,c)+`<g transform="translate(270 112)">${[0,1,2].map(i=>`<rect x="${(i%2)*14}" y="${18-Math.floor(i/2)*10}" width="13" height="9" rx="1.5" fill="${c}" fill-opacity=".7"/>`).join('')}</g>`,
    cold:c=>ground(c)+factory(80,150,62,c)+`<g transform="translate(155 98)" stroke="#BDF4FF" stroke-width="2" stroke-linecap="round"><path d="M0 -12 V12 M-10 -6 L10 6 M-10 6 L10 -6"><animateTransform attributeName="transform" type="rotate" from="0" to="360" dur="8s" repeatCount="indefinite"/></path></g>`+`<g><animateTransform attributeName="transform" type="translate" values="40 0;0 0;0 0;40 0" keyTimes="0;.35;.75;1" dur="6s" repeatCount="indefinite"/><rect x="236" y="112" width="44" height="22" rx="2" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/><rect x="280" y="118" width="18" height="16" rx="2" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/><circle cx="248" cy="136" r="5" fill="#020B07" stroke="${c}"/><circle cx="288" cy="136" r="5" fill="#020B07" stroke="${c}"/></g>`+blink(96,90,'#BDF4FF',2),
    ikan:c=>`<rect x="0" y="96" width="320" height="74" fill="#0E3550"/>`+[0,1,2].map(j=>`<path d="M0 ${104+j*20} q20 -6 40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0 t40 0" stroke="#4FD8E8" stroke-opacity=".35" fill="none"><animateTransform attributeName="transform" type="translate" values="0 0;-40 0" dur="${3+j}s" repeatCount="indefinite"/></path>`).join('')+[50,120,190].map(x=>`<g><rect x="${x}" y="92" width="58" height="14" fill="#0B1F15" stroke="${c}" stroke-width="1.5"/><path d="M${x} 106 v26 h58 v-26" fill="${c}" fill-opacity=".08" stroke="${c}" stroke-dasharray="3 3"/><animateTransform attributeName="transform" type="translate" values="0 0;0 2;0 0" dur="2.6s" repeatCount="indefinite"/></g>`).join('')+[0,1].map(j=>`<path d="M0 0 q8 -6 16 0 q-8 6 -16 0 m16 0 l6 -5 v10 z" fill="#8FB3FF" transform="translate(${70+j*70} ${122-j*4})"><animateTransform attributeName="transform" type="translate" values="${70+j*70} ${122-j*4};${104+j*70} ${120-j*4};${70+j*70} ${122-j*4}" dur="${4+j}s" repeatCount="indefinite"/></path>`).join('')+`<path d="M262 92 v-30 l20 10 -20 10" fill="none" stroke="${c}"/>`,
