          <table class="lp-t">${row('Status dalam berkas',v.st)}${row('Dasar data',v.q==='Non LBS'?'Bukan lahan baku sawah 2024 (Non LBS)':'Lahan Baku Sawah 2024')}${row('Fungsi kawasan hutan',v.hut||'Tidak tercantum pada atribut berkas')}${row('Luas',`<span class="num">${fh(v.ha,1)} ha</span> (seluruh bagian areal ini)`)}${row('Sebaran per kecamatan (perkiraan)',v.kc.map(x=>`${x[0]} ${fh(x[1],x[1]<100?1:0)} ha`).join('; ')||'Areal terlalu kecil untuk dihitung per kecamatan')}${v.xi?row('Berimpit izin lokasi',`<span class="num">± ${fh(v.xi,1)} ha</span>`):''}${v.ket?row('Keterangan',v.ket):''}${row('Sumber',LSRC.tani)}</table>
