    const def={bm:'none',tm:'none',grid:true,prw:false,air:true,dp:false,'j:n':true,'j:k':true,'j:d':false,'j:x':false,'j:r':true,kec:true,kecl:true,nb:true,desa:!!BATAS.desa.length,desal:false,sig:false,izin:false,lp2b:false,lcp2b:false,lbsh:false,tdk:false,hulu:hil,alur:hil};
