    const em=String(K.email_layanan_data||K.email||'').trim(),emOk=/^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]+$/.test(em);
    const wa=String(K.whatsapp_layanan_data||K.whatsapp_pengaduan||'').replace(/\D/g,'').replace(/^0/,'62');
    const gf=/^https:\/\/\S+$/i.test(String(K.form_pendaftaran_mitra||'').trim())?String(K.form_pendaftaran_mitra).trim():'';
    const SKB=[[0,1e9,'Mikro'],[1e9,5e9,'Kecil'],[5e9,1e10,'Menengah'],[1e10,Infinity,'Besar']];
    const need=[['saluran','Saluran pendaftaran'],['nama_usaha','Nama usaha'],['bentuk_usaha','Bentuk usaha'],['nib','NIB'],['sektor','Sektor'],['produk','Produk/komoditas'],['kecamatan','Kecamatan'],['desa','Desa/kelurahan'],['skala','Skala usaha'],['kebutuhan','Kebutuhan kemitraan'],['uraian','Uraian kemitraan'],['pj','Nama penanggung jawab'],['jabatan','Jabatan'],['telp','Telepon/WhatsApp'],['alamat','Alamat usaha']];
    const tg=d=>{try{return d.toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}catch(_){return d.toISOString().slice(0,10)}};
