      let warn='';if(mo){const m=+mo,hit=SKB.find(([a,b])=>m>a&&m<=b||(a===0&&m<=b));if(hit&&hit[2]!==val('skala'))warn=`Modal usaha Rp${m.toLocaleString('id-ID')} termasuk skala ${hit[2]} menurut PP 7/2021 Pasal 35 ayat (3), sedangkan pilihan skala usaha ${val('skala')}. Periksa kembali; petugas mencocokkannya dengan data OSS (SOP-05 langkah 4 dan 5).`;}
      msg.textContent='';
