    const q=s=>root.querySelector(s),stage=q('.mt-stage');
    const G=GIS(stage,{id:'mtg',geo:GM,kmax:80,light:true,lp:false,wheel:true,layers:[],mini:KO.map(k=>`<path d="${k.d}"/>`).join(''),attr:'Batas desa: BIG 2020 · RDTR Muara Teweh 2021 · Jalan & perairan: CSRT Worldview 2020, DPUPR',onView:()=>posPop(),onBmFail:()=>{st.bm='none';const r=q('input[data-bm="none"]');if(r)r.checked=true;}});
